import React from "react";


const Products = () => {
  const productList = [
    {
      image: "https://via.placeholder.com/150",
      name: "Headphones",
      category: "Electronics",
      price: 2999,
      brand: "Sony",
    },
    {
      image: "https://via.placeholder.com/150",
      name: "Shoes",
      category: "Footwear",
      price: 1999,
      brand: "Nike",
    },
    {
      image: "https://via.placeholder.com/150",
      name: "Watch",
      category: "Accessories",
      price: 3499,
      brand: "Boat",
    },
    {
      image: "https://via.placeholder.com/150",
      name: "Backpack",
      category: "Travel",
      price: 1299,
      brand: "Wildcraft",
    },
  ];

  return (
    <div>
      <h1 style={{ textAlign: "center", marginTop: "40px" }}>PRODUCTS</h1>
      <div className="product-grid">
        {productList.map((product, index) => (
          <div key={index} className="square-card">
            <img src={product.image} alt={product.name} className="square-img" />
            <div className="square-info">
              <h4>{product.name}</h4>
              <p>{product.category}</p>
              <p>₹{product.price}</p>
              <p>{product.brand}</p>
              <button className="square-btn">Buy</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Products;
